@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 text-white me-2" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="max-width: 260px;"
            @onchange="OnWarehouseSelected" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in Services.WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseState WarehouseState
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
    Low Stock
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
        WarehouseState.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertCountChanged -= _handler;
            WarehouseState.OnChange -= _handler;
        }
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.CurrentWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4">
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="text-danger">@AlertService.CurrentLowStockCount items</span>
            }
            else
            {
                <span class="text-success">All stocked</span>
            }
        </p>
        <p class="text-muted">
            Polling every 10 seconds for items below minimum levels.
        </p>
    </div>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
        WarehouseState.OnChange += _handler;

        // Start polling when this page is visible.
        AlertService.Subscribe();
    }

    public void Dispose()
    {
        // Stop polling when the user leaves this page.
        AlertService.Unsubscribe();

        if (_handler is not null)
        {
            AlertService.OnAlertCountChanged -= _handler;
            WarehouseState.OnChange -= _handler;
        }
    }
}

