@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 text-white me-2" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="max-width: 260px;"
            @onchange="OnWarehouseSelected" value="@WarehouseState.CurrentWarehouseId">
        @foreach (var wh in Services.WarehouseState.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

